/* ---- Resources ------------------------------------------------------------- */
static void rt_res_final(void* p) {
    RtRes* r = (RtRes*)p;
    if (r->state == 1) { r->state = 2; r->release(r); r->state = 0; }
}
static inline void rt_res_release(void* p) { if (p) rt_res_final(p); }
static void std__io__files__FileHandle__release(RtRes* r) { fclose(((Res_std__io__files__FileHandle*)r)->value); }
static Res_std__io__files__FileHandle* std__io__files__FileHandle__new(RtMem* m, Ext_std__io__files__FileHandle v, int line) {
    if (!(v != NULL && (intptr_t)v != -1)) return NULL;          /* C failed: no resource */
    Res_std__io__files__FileHandle* c = (Res_std__io__files__FileHandle*)rt_mem_alloc(m, sizeof(Res_std__io__files__FileHandle), line);
    c->h.state = 1;
    c->h.release = std__io__files__FileHandle__release;
    c->value = v;
    rt_mem_on_free(m, rt_res_final, c, line);
    return c;
}
static inline Ext_std__io__files__FileHandle std__io__files__FileHandle__get(Res_std__io__files__FileHandle* c, int line) {
    if (!c || c->h.state == 0) rt_panic("a released FileHandle was used", line);
    return c->value;
}
